import { z } from "zod";
import { COMPONENT_IDS } from "../hardware/ids.ts";
import { PLATFORMS, DIFFICULTIES, WIRE_COLORS } from "../content/schema.ts";

/**
 * A project generated by the AI Project Generator (POST /api/build). Same circuit format as a guide
 * (instances + connections, checked by lib/hardware/check.ts) but in one language, plus a CAD model.
 * Everything here comes from a model, so it is validated as untrusted input before anything renders it.
 */
const text = (max: number) => z.string().trim().min(1).max(max);
const mm = (min: number, max: number) => z.number().finite().min(min).max(max);
const vec3 = (min: number, max: number) => z.tuple([mm(min, max), mm(min, max), mm(min, max)]);

const Rotation = vec3(-360, 360);
const Shape = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("box"), size: vec3(0.2, 400), at: vec3(-500, 500), rotate: Rotation.optional(), subtract: z.boolean().optional(),
    /** Rounds the four vertical edges (enclosure corners). */
    radius: mm(0, 100).optional(),
  }).strict(),
  z.object({ type: z.literal("cylinder"), r: mm(0.2, 200), h: mm(0.2, 400), at: vec3(-500, 500), rotate: Rotation.optional(), subtract: z.boolean().optional() }).strict(),
]);
export type CadShape = z.infer<typeof Shape>;

const CadPart = z.object({
  name: text(60),
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/),
  printed: z.boolean(),
  /** Printed or custom parts: primitives in world coordinates. */
  shapes: z.array(Shape).min(1).max(40).optional(),
  /** Bought parts: a registry component drawn from its built-in model, its bottom-face centre placed at `at`. */
  component: z.enum(COMPONENT_IDS).optional(),
  at: vec3(-500, 500).optional(),
  rotate: Rotation.optional(),
  /** Assembly step (1-based) in which this part goes in; drives the assembly animation. */
  step: z.number().int().min(1).max(16).optional(),
}).strict().refine((p) => Boolean(p.shapes?.length) || Boolean(p.component), { message: "a part needs shapes or a component" });
export type CadPart = z.infer<typeof CadPart>;

export const CadSchema = z.object({
  /** Each part is one printable or bought piece: shapes are unioned, then `subtract` shapes are cut out. Millimetres, Z up. */
  parts: z.array(CadPart).min(1).max(32),
}).strict();
export type Cad = z.infer<typeof CadSchema>;

const InstanceId = z.string().regex(/^[a-z][a-z0-9_]{0,23}$/);
const Endpoint = z.string().regex(/^[a-z][a-z0-9_]{0,23}\.[A-Za-z0-9_+\-/.]{1,16}$/);

export const ProjectSchema = z.object({
  title: text(90),
  summary: text(400),
  platform: z.enum(PLATFORMS),
  board: z.enum(COMPONENT_IDS),
  difficulty: z.enum(DIFFICULTIES),
  hours: z.number().min(0.5).max(80),
  costUsd: z.number().min(1).max(1000),
  /** Shopping list. `component` is set for registry parts; screws, filament etc. have only a name. */
  parts: z.array(z.object({
    component: z.enum(COMPONENT_IDS).optional(),
    name: text(80),
    qty: z.number().int().min(1).max(200),
    spec: text(140),
  }).strict()).min(2).max(40),
  plan: z.array(z.object({ phase: text(80), tasks: z.array(text(200)).min(1).max(8) }).strict()).min(2).max(8),
  instances: z.array(z.object({ id: InstanceId, component: z.enum(COMPONENT_IDS), label: z.string().max(24).optional() }).strict()).max(24),
  connections: z.array(z.object({ from: Endpoint, to: Endpoint, color: z.enum(WIRE_COLORS), note: z.string().max(160).optional() }).strict()).min(1).max(60),
  assembly: z.array(z.object({ title: text(90), body: text(900) }).strict()).min(3).max(16),
  code: z.array(z.object({
    filename: z.string().regex(/^[A-Za-z0-9_.-]{1,40}$/),
    language: z.enum(["cpp", "python", "bash"]),
    source: z.string().min(20).max(24_000),
    libraries: z.array(z.string().max(80)).max(12),
  }).strict()).min(1).max(4),
  cad: CadSchema,
  safety: z.array(text(300)).max(6),
}).strict();
export type Project = z.infer<typeof ProjectSchema>;
/** What the language model writes: everything but the 3D model, which lib/build/layout.ts builds from the parts. */
export const ProjectInputSchema = ProjectSchema.omit({ cad: true });
export type ProjectInput = z.infer<typeof ProjectInputSchema>;

/** POST /api/build body. The idea is short free text; a longer body is not from our UI. */
export const MAX_IDEA_CHARS = 600;
export const BuildRequestSchema = z.object({
  locale: z.enum(["en", "ru", "kk"]),
  idea: z.string().trim().min(8).max(MAX_IDEA_CHARS),
}).strict();

/**
 * Pulls the JSON object out of a model reply: models often wrap it in ```json fences or add a sentence
 * before it. Returns undefined when no parsable object is found.
 */
export function extractJson(reply: string): unknown {
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(reply)?.[1];
  for (const candidate of [fenced, reply]) {
    if (!candidate) continue;
    const start = candidate.indexOf("{");
    const end = candidate.lastIndexOf("}");
    if (start < 0 || end <= start) continue;
    try { return JSON.parse(candidate.slice(start, end + 1)); } catch { /* try the next candidate */ }
  }
  return undefined;
}

/** Zod issues as short "path: message" lines a model can act on when asked to repair its output. */
export function describeIssues(error: z.ZodError, limit = 25): string[] {
  return error.issues.slice(0, limit).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`);
}
